-- Fotos (mínimo de 3 por atração) das lojas e mercados de Orlando e do Drawn to Life.
-- Fonte: Wikimedia Commons (licenças livres), com crédito na legenda. As imagens são miniaturas de
-- 1280px servidas pelo próprio Wikimedia, então não gastam cota do Supabase Storage. A maioria mostra
-- outra unidade da mesma rede, e a legenda diz isso. Trocar por fotos próprias quando houver.
insert into attraction_photos (attraction_id, url, "order", caption)
select a.id, v.url, v.ord, v.caption
from attractions a
join cities c on c.id = a.city_id and c.slug = 'orlando'
join (values
